versions.variantCss:
.wemd-image-text-row[data-variant="bytedance-row-card"] {
  background: var(--wemd-bg-card);
  border-radius: var(--wemd-border-radius);
  padding: 16px;
  margin: 12px 0;
  border: 1px solid var(--wemd-border-soft);
  box-shadow: var(--wemd-shadow);
}
.wemd-image-text-row[data-variant="bytedance-row-card"] .wemd-component-body {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
}
.wemd-image-text-row[data-variant="bytedance-row-card"] .wemd-component-body .wemd-child-1 {
  flex: 0 0 80px;
  width: 80px;
  height: 80px;
  background: var(--wemd-bg-soft);
  border-radius: var(--wemd-border-radius);
  margin: 0 16px 0 0;
  overflow: hidden;
}
.wemd-image-text-row[data-variant="bytedance-row-card"] .wemd-component-body .wemd-child-2 {
  flex: 1;
  color: var(--wemd-text-strong);
  font-size: 16px;
  font-weight: 700;
  margin: 0 0 4px 0;
}
.wemd-image-text-row[data-variant="bytedance-row-card"] .wemd-component-body .wemd-child-3 {
  flex: 1;
  color: var(--wemd-text-soft);
  font-size: 13px;
  line-height: 1.6;
  margin: 0;
}
